/**
 * A writer for MP4/M4A fixtures, generated by code: one audio track, with
 * every box a browser needs to decode it. AAC samples are a silent AAC-LC
 * stereo block, so Chromium and Firefox decode them. Options produce the
 * tables and boxes the walker must refuse.
 */

const SILENT_STEREO_BLOCK = [0x21, 0x00, 0x49, 0x90, 0x02, 0x19, 0x00, 0x23, 0x80];
const AAC_RATES = [
  96_000, 88_200, 64_000, 48_000, 44_100, 32_000, 24_000, 22_050, 16_000, 12_000, 11_025, 8_000,
  7_350,
];

const u16 = (v: number) => [(v >> 8) & 0xff, v & 0xff];
const u32 = (v: number) => [(v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff];
const text = (s: string) => [...s].map((c) => c.charCodeAt(0));
const box = (type: string, ...body: number[][]) => {
  const content = body.flat();
  return [...u32(8 + content.length), ...text(type), ...content];
};
const full = (type: string, version: number, flags: number, ...body: number[][]) =>
  box(type, [version, ...u32(flags).slice(1)], ...body);
const MATRIX = [0x00010000, 0, 0, 0, 0x00010000, 0, 0, 0, 0x40000000].flatMap(u32);

export interface Mp4Options {
  readonly codec?: "aac" | "alac";
  readonly sampleRate?: number;
  /** The AAC channel configuration written in the AudioSpecificConfig. */
  readonly channelConfiguration?: number;
  readonly samples: number;
  readonly samplesPerChunk?: number;
  /** mdhd's duration, in its timescale (the core rate), instead of the real one. */
  readonly duration?: number;
  /** Move the last chunk's offset past the end of the file. */
  readonly chunkOutsideFile?: boolean;
  /** The sample count written in stsz, instead of the real one. */
  readonly stszCount?: number;
  /** A second audio track. */
  readonly secondAudioTrack?: boolean;
  /** A moof box after mdat, as in a fragmented file. */
  readonly fragmented?: boolean;
  /** The ALAC frame length, for codec "alac". */
  readonly alacFrameLength?: number;
}

function sampleEntry(options: Mp4Options): number[] {
  const rate = options.sampleRate ?? 44_100;
  const channels = 2;
  const audioFields = [
    ...new Array(6).fill(0),
    ...u16(1), // reserved, data reference index
    ...u16(0),
    ...u16(0),
    ...u32(0), // version, revision, vendor
    ...u16(channels),
    ...u16(16),
    ...u16(0),
    ...u16(0),
    ...u32((rate & 0xffff) * 65_536),
  ];
  if (options.codec === "alac") {
    const config = [
      ...u32(options.alacFrameLength ?? 4_096),
      0,
      16,
      40,
      10,
      14,
      channels,
      ...u16(255),
      ...u32(0),
      ...u32(0),
      ...u32(rate),
    ];
    return box("alac", audioFields, full("alac", 0, 0, config));
  }
  const rateIndex = AAC_RATES.indexOf(rate);
  const asc = (2 << 11) | (rateIndex << 7) | ((options.channelConfiguration ?? 2) << 3);
  const decoderSpecific = [0x05, 2, ...u16(asc)];
  const decoderConfig = [
    0x04,
    13 + decoderSpecific.length,
    0x40,
    0x15,
    0,
    0,
    0,
    ...u32(128_000),
    ...u32(128_000),
    ...decoderSpecific,
  ];
  const es = [0x03, 3 + decoderConfig.length + 3, ...u16(1), 0, ...decoderConfig, 0x06, 1, 2];
  return box("mp4a", audioFields, full("esds", 0, 0, es));
}

function trak(options: Mp4Options, chunkOffsets: number[], trackId: number): number[] {
  const rate = options.sampleRate ?? 44_100;
  const perChunk = options.samplesPerChunk ?? 5;
  const sampleSize = options.codec === "alac" ? 32 : SILENT_STEREO_BLOCK.length;
  const duration =
    options.duration ??
    options.samples * (options.codec === "alac" ? (options.alacFrameLength ?? 4_096) : 1_024);
  const stbl = box(
    "stbl",
    full("stsd", 0, 0, u32(1), sampleEntry(options)),
    full(
      "stts",
      0,
      0,
      u32(1),
      u32(options.samples),
      u32(options.codec === "alac" ? (options.alacFrameLength ?? 4_096) : 1_024),
    ),
    full(
      "stsc",
      0,
      0,
      u32(options.samples % perChunk === 0 ? 1 : 2),
      u32(1),
      u32(perChunk),
      u32(1),
      ...(options.samples % perChunk === 0
        ? []
        : [
            [
              ...u32(Math.ceil(options.samples / perChunk)),
              ...u32(options.samples % perChunk),
              ...u32(1),
            ],
          ]),
    ),
    full("stsz", 0, 0, u32(sampleSize), u32(options.stszCount ?? options.samples)),
    full("stco", 0, 0, u32(chunkOffsets.length), chunkOffsets.flatMap(u32)),
  );
  const minf = box(
    "minf",
    full("smhd", 0, 0, u16(0), u16(0)),
    box("dinf", full("dref", 0, 0, u32(1), full("url ", 0, 1))),
    stbl,
  );
  const mdia = box(
    "mdia",
    full("mdhd", 0, 0, u32(0), u32(0), u32(rate), u32(duration), u16(0x55c4), u16(0)),
    full("hdlr", 0, 0, u32(0), text("soun"), new Array(12).fill(0), [0]),
    minf,
  );
  const tkhd = full(
    "tkhd",
    0,
    7,
    u32(0),
    u32(0),
    u32(trackId),
    u32(0),
    u32(duration),
    new Array(8).fill(0),
    u16(0),
    u16(0),
    u16(0x0100),
    u16(0),
    MATRIX,
    u32(0),
    u32(0),
  );
  return box("trak", tkhd, mdia);
}

/** An M4A file of `samples` silent samples, in chunks of `samplesPerChunk`. */
export function mp4File(options: Mp4Options): Uint8Array<ArrayBuffer> {
  const rate = options.sampleRate ?? 44_100;
  const perChunk = options.samplesPerChunk ?? 5;
  const sampleBytes = options.codec === "alac" ? new Array(32).fill(0) : SILENT_STEREO_BLOCK;
  const chunks = Math.ceil(options.samples / perChunk);
  const ftyp = box("ftyp", text("M4A "), u32(0), text("M4A "), text("isom"));
  const build = (offsets: number[]) => {
    const tracks = [trak(options, offsets, 1)];
    if (options.secondAudioTrack) tracks.push(trak(options, offsets, 2));
    const mvhd = full(
      "mvhd",
      0,
      0,
      u32(0),
      u32(0),
      u32(rate),
      u32(options.samples * 1_024),
      u32(0x00010000),
      u16(0x0100),
      new Array(10).fill(0),
      MATRIX,
      new Array(24).fill(0),
      u32(3),
    );
    return box("moov", mvhd, ...tracks);
  };
  // Lay out once to learn the moov's size, then write the real offsets.
  const moovSize = build(new Array(chunks).fill(0)).length;
  const mdatStart = ftyp.length + moovSize + 8;
  const offsets: number[] = [];
  const data: number[] = [];
  for (let s = 0; s < options.samples; s += 1) {
    if (s % perChunk === 0) offsets.push(mdatStart + data.length);
    data.push(...sampleBytes);
  }
  if (options.chunkOutsideFile) offsets[offsets.length - 1] = mdatStart + data.length + 1_000;
  const file = [...ftyp, ...build(offsets), ...box("mdat", data)];
  if (options.fragmented) file.push(...box("moof", full("mfhd", 0, 0, u32(1))));
  return Uint8Array.from(file);
}
